# oracle. `🧲️procedural-example-booleans` measures the tessellated boolean result with parry3d's
# own signed-volume integrator to cross-check this kernel's `solid_volume`.
parry3d = "0.17"
# 🔮 Test-only EXACT-ARITHMETIC oracle for `🧊️brep/…/➡️vector/⚖️predicates` (never a
# `[dependencies]` entry, never reachable from a production target). The predicates' exact path is
# nonoverlapping floating-point expansion arithmetic (Shewchuk error-free transformations); this
# recomputes the SAME determinants in arbitrary-precision rationals — a completely different
# representation and a completely different algorithm, written by someone else — so the claim "the
# expansion path returns the exact sign" rests on an independent derivation rather than on the
# expansion code agreeing with itself (ticket 26/09/09/PROCEDURAL-3D-END-TO-END,
# `📓️kernel-performance-2026-09-13.md`).
num-rational = "0.4"
# 🔮 Test-only RASTER oracle (never a `[dependencies]` entry): resvg renders the svg leaf's output
# of the same drawing the `🖊️drawing → 📷️png` rasterizer paints, and hayro renders the pdf leaf's
# output, so neither raster expectation is computed by this repository's own code.
resvg = "0.45.1"
hayro = "0.4.0"
